function y = smooth_dke_yp(x,width,typ)%%	Columnwise data smoothing%%	Input:%%		- x: data matrix [n,m]%		- width: smoothing width [1,1]%		- typ: 'gauss'ian or 'rect'angular (string) [1,p]%		  (default = 'gaus')%%	Output:%	%		- y: smoothed data [n,m]%%by Y.PEYSSON CEA-DRFC 02/07/92 <peysson@drfc.cad.cea.fr>%revised for MatLab 4.2 05/12/94%revised for MatLab 5.2 (31/08/2000) %if nargin < 2,	infoyp(2,'Wrong number of input arguments for smooth_dke_yp');	return;endif nargin == 2,	typ = 'gaus'; end%if  width ~= 0,	if typ=='gaus'			width = width*2;        	w = (-width:width)/width*2;        	w = exp(-w.^2);	else		w = ones(-width:width);	end	w = w/sum(w);	n = size(x);	if n(1,1)==1, x = x'; end	for i = 1:n(1,2)        	xf = conv(x(:,i),w);        	y(:,i) = xf(width+1:n(1,1)+width);	end      else	y = x;end                                  